class BinaryAnalyzer:
    """Analyzes binary files and memory"""

    def __init__(self):
        self.exploit_analyzer = ExploitAnalyzer()
        self.memory_inspector = MemoryInspector()
        self.network_analyzer = NetworkPayloadAnalyzer()
        self.disasm_engine = DisassemblyEngine()

    def analyze_binary(self, data: bytes) -> Dict:
        """Comprehensive binary analysis"""
        return {
            'hex_analysis': self._hex_analysis(data),
            'string_extraction': self._extract_strings(data),
            'pattern_detection': self._detect_patterns(data)
        }

    def _hex_analysis(self, data: bytes) -> Dict:
        return {
            'hex': data.hex(),
            'size': len(data),
            'entropy': self._calculate_entropy(data)
        }

    def _extract_strings(self, data: bytes) -> List[str]:
        """Extract printable strings from binary data"""
        strings = []
        current_string = bytearray()

        for byte in data:
            if 32 <= byte <= 126:
                current_string.append(byte)
            else:
                if len(current_string) >= 4:
                    strings.append(current_string.decode('ascii', errors='ignore'))
                current_string = bytearray()

        return strings

    def _detect_patterns(self, data: bytes) -> List[str]:
        patterns = []
        if b'\x90\x90\x90\x90' in data:
            patterns.append('nop_sled')
        if b'\xe8\x00\x00\x00\x00' in data:
            patterns.append('call_instruction')
        return patterns

    def _calculate_entropy(self, data: bytes) -> float:
        """Calculate Shannon entropy"""
        byte_counts = Counter(data)
        entropy = 0
        for count in byte_counts.values():
            probability = count / len(data)
            entropy -= probability * math.log2(probability) if probability > 0 else 0
        return entropy


class ExploitAnalyzer:
    """Analyzes exploit patterns"""

    def detect_rop_chains(self, data: bytes) -> List[Dict]:
        """Detect ROP gadget chains"""
        rop_gadgets = []
        endings = [b'\xc3', b'\xcb', b'\xc2']

        for i in range(len(data)-1):
            for ending in endings:
                if data[i:i+len(ending)] == ending:
                    gadget = data[max(0, i-12):i+len(ending)]
                    rop_gadgets.append({
                        'offset': max(0, i-12),
                        'bytes': gadget.hex(),
                        'size': len(gadget)
                    })
        return rop_gadgets

    def detect_shellcode(self, data: bytes) -> List[Dict]:
        """Detect shellcode patterns"""
        shellcode_patterns = []
        patterns = {
            'syscall_exec': b'\x0f\x05',
            'stack_pivot': b'\x94',
            'get_eip': b'\xe8',
        }

        for name, pattern in patterns.items():
            offsets = [i for i in range(len(data)-len(pattern)) if data[i:i+len(pattern)] == pattern]
            if offsets:
                shellcode_patterns.append({
                    'type': name,
                    'offsets': offsets,
                    'size': len(pattern)
                })
        return shellcode_patterns


class MemoryInspector:
    """Inspects memory structures"""

    def analyze_memory_layout(self, data: bytes) -> Dict:
        return {
            'stack_frames': self._identify_stack_frames(data),
            'heap_chunks': self._analyze_heap_structures(data),
            'vtables': self._find_vtables(data)
        }

    def _identify_stack_frames(self, data: bytes) -> List[Dict]:
        """Identify stack frame patterns"""
        frames = []
        patterns = [
            b'\x55\x48\x89\xe5',
            b'\x55\x89\xe5'
        ]

        for pattern in patterns:
            offsets = [i for i in range(len(data)-len(pattern)) if data[i:i+len(pattern)] == pattern]
            for offset in offsets:
                frames.append({
                    'offset': offset,
                    'type': 'frame_setup'
                })
        return frames

    def _analyze_heap_structures(self, data: bytes) -> List[Dict]:
        """Analyze heap chunk patterns"""
        heap_chunks = []
        chunk_patterns = {
            'glibc': b'\x00\x00\x00\x00',
            'windows': b'\x00\x00\x00\x08',
        }

        for i in range(0, len(data) - 8, 8):
            header = data[i:i+8]
            for heap_type, pattern in chunk_patterns.items():
                if pattern in header:
                    size = int.from_bytes(header[:4], byteorder='little')
                    heap_chunks.append({
                        'offset': i,
                        'type': heap_type,
                        'size': size
                    })
        return heap_chunks

    def _find_vtables(self, data: bytes) -> List[Dict]:
        """Identify virtual table structures"""
        vtables = []
        pointer_size = 8

        for i in range(0, len(data) - pointer_size * 4, pointer_size):
            pointers = []
            for j in range(4):
                ptr = int.from_bytes(data[i + j*pointer_size:i + (j+1)*pointer_size], 
                                    byteorder='little')
                if ptr > 0x400000:
                    pointers.append(ptr)

            if len(pointers) >= 3:
                vtables.append({
                    'offset': i,
                    'pointers': pointers,
                    'count': len(pointers)
                })
        return vtables


class NetworkPayloadAnalyzer:
    """Analyzes network payloads"""

    def analyze_network_data(self, data: bytes) -> Dict:
        return {
            'protocol_signatures': self._identify_protocols(data),
            'payload_structure': self._analyze_payload_structure(data),
            'embedded_commands': self._find_command_patterns(data)
        }

    def _identify_protocols(self, data: bytes) -> List[str]:
        """Identify network protocols"""
        protocols = []
        if data.startswith(b'HTTP/'):
            protocols.append('http')
        if b'SSH-' in data:
            protocols.append('ssh')
        if data.startswith(b'\x16\x03'):
            protocols.append('tls')
        return protocols

    def _analyze_payload_structure(self, data: bytes) -> Dict:
        """Analyze payload structure"""
        return {
            'size': len(data),
            'header_size': min(len(data), 64),
            'payload_type': self._identify_payload_type(data)
        }

    def _identify_payload_type(self, data: bytes) -> str:
        """Identify payload type"""
        if data.startswith(b'HTTP/'):
            return 'http'
        if data.startswith(b'{') and data.endswith(b'}'):
            return 'json'
        if data.startswith(b'<?xml'):
            return 'xml'
        return 'unknown'

    def _find_command_patterns(self, data: bytes) -> List[Dict]:
        """Find command patterns"""
        commands = []
        patterns = {
            'shell_cmd': br'(sh|bash|cmd|powershell)',
            'sql_query': br'(SELECT|INSERT|UPDATE|DELETE)',
        }

        for cmd_type, pattern in patterns.items():
            matches = re.finditer(pattern, data)
            for match in matches:
                commands.append({
                    'type': cmd_type,
                    'offset': match.start(),
                    'command': match.group().decode(errors='ignore')
                })
        return commands


class DisassemblyEngine:
    """Disassembly and instruction analysis"""

    def disassemble(self, data: bytes) -> List[Dict]:
        """Disassemble binary data"""
        if Cs is None:
            return []

        try:
            md = Cs(CS_ARCH_X86, CS_MODE_64)
            instructions = []
            for inst in md.disasm(data, 0):
                instructions.append({
                    'address': hex(inst.address),
                    'mnemonic': inst.mnemonic,
                    'operands': inst.op_str,
                    'bytes': inst.bytes.hex()
                })
            return instructions
        except Exception as e:
            logging.error(f"Disassembly error: {e}")
            return []


