class InjectionVisualizer:
    """Visualizes code injection patterns"""

    def __init__(self):
        self.output_dir = Path("injection_analysis")
        self.output_dir.mkdir(exist_ok=True)
        self.reports_dir = self.output_dir / "reports"
        self.reports_dir.mkdir(exist_ok=True)
        self.html_dir = self.output_dir / "html_reports"
        self.html_dir.mkdir(exist_ok=True)

        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        self.report_file = self.reports_dir / f'detailed_injection_report_{timestamp}.txt'
        self.json_file = self.reports_dir / f'injection_findings_{timestamp}.json'
        self.csv_file = self.reports_dir / f"injection_summary_{timestamp}.csv"

        self.patterns_to_track = {
            'nop': {'pattern': b'\x90', 'name': 'NOP Sled', 'min_length': 4},
            'int3': {'pattern': b'\xCC', 'name': 'INT3 Breakpoint', 'min_length': 2},
            'push_ret': {'pattern': b'\x54\xC3', 'name': 'PUSH/RET', 'min_length': 2},
        }

        self.shellcode_patterns = {
            'shell_code': rb'\x55\x8B\xEC|\x90{4,}',
            'script_injection': rb'(eval|exec|system)',
            'memory_manipulation': rb'(VirtualAlloc|WriteProcessMemory)',
            'dll_injection': rb'(LoadLibrary|GetProcAddress)',
        }

    def analyze_shellcode(self, shellcode_bytes: bytes) -> Dict:
        """Analyze shellcode"""
        return {
            'hex': shellcode_bytes.hex(),
            'size': len(shellcode_bytes),
            'patterns': self._find_patterns(shellcode_bytes)
        }

    def _find_patterns(self, data: bytes) -> List[str]:
        """Find patterns in data"""
        patterns = []
        for pattern_name, pattern_data in self.patterns_to_track.items():
            if pattern_data['pattern'] in data:
                patterns.append(pattern_name)
        return patterns

    def generate_report(self, findings: List[Dict]) -> str:
        """Generate analysis report"""
        report = f"Injection Analysis Report\nGenerated: {datetime.now()}\n\n"
        report += f"Total Findings: {len(findings)}\n\n"

        for finding in findings:
            report += f"Type: {finding.get('type', 'unknown')}\n"
            report += f"Location: {finding.get('location', 'unknown')}\n"
            report += f"Process: {finding.get('process_name', 'unknown')}\n\n"

        return report


# ============================================================================
# MAIN COUNTER CLASS
# ============================================================================

class MeliodasCounter:
    """Main counter consolidating all analysis modules"""

    def __init__(self):
        self.injection_analyzer = CodeInjectionAnalyzer()
        self.injection_visualizer = InjectionVisualizer()
        self.binary_analyzer = BinaryAnalyzer()
        self.network_monitor = TransferMonitor()
        self.encryption_detector = EncryptionDetector()
        self.anomaly_detector = NetworkAnomalyDetector()
        self.protocol_analyzer = ProtocolBehaviorAnalyzer()

    def run_injection_analysis(self):
        """Run code injection analysis"""
        logging.info("Starting injection analysis...")
        self.injection_analyzer.analyze_all_processes()

    def analyze_memory(self, pid: int) -> Dict:
        """Analyze process memory"""
        findings = self.injection_analyzer.scan_process_memory(pid)
        return {
            'pid': pid,
            'findings': findings,
            'count': len(findings)
        }

    def analyze_binary_file(self, filepath: str) -> Dict:
        """Analyze binary file"""
        try:
            with open(filepath, 'rb') as f:
                data = f.read()
            return self.binary_analyzer.analyze_binary(data)
        except Exception as e:
            logging.error(f"Error analyzing {filepath}: {e}")
            return {}

    def generate_full_report(self, data: bytes) -> Dict:
        """Generate comprehensive analysis report"""
        return {
            'binary_analysis': self.binary_analyzer.analyze_binary(data),
            'shellcode_analysis': self.injection_visualizer.analyze_shellcode(data),
            'network_analysis': self.binary_analyzer.network_analyzer.analyze_network_data(data),
            'memory_analysis': self.binary_analyzer.memory_inspector.analyze_memory_layout(data),
            'exploit_detection': {
                'rop_chains': self.binary_analyzer.exploit_analyzer.detect_rop_chains(data),
                'shellcode': self.binary_analyzer.exploit_analyzer.detect_shellcode(data)
            },
            'encryption': self.encryption_detector.detect_encryption(data)
        }

    def scan_processes(self) -> List[Dict]:
        """Scan all running processes"""
        results = []
        for proc in psutil.process_iter(['pid', 'name']):
            try:
                findings = self.injection_analyzer.scan_process_memory(proc.pid)
                if findings:
                    results.append({
                        'process_name': proc.name(),
                        'pid': proc.pid,
                        'findings': findings
                    })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
        return results


# ============================================================================
# COMMAND LINE INTERFACE
# ============================================================================

def main():
    """Main entry point"""
    counter = MeliodasCounter()

    # Example usage
    print("Meliodas Counter - Consolidated Malware Analysis Tool")
    print("=" * 60)

    # Scan current processes
    print("\nScanning running processes...")
    results = counter.scan_processes()

    if results:
        print(f"Found {len(results)} processes with detections:")
        for result in results:
            print(f"  - {result['process_name']} (PID: {result['pid']}): {len(result['findings'])} findings")
    else:
        print("No detections found in running processes.")

    print("\nAnalysis complete. Check injection_analysis directory for detailed reports.")


if __name__ == "__main__":
    main()

