class EncryptionDetector:
    """Detects encrypted data patterns"""

    def detect_encryption(self, data: bytes) -> Dict:
        return {
            'entropy': self._calculate_entropy(data),
            'is_likely_encrypted': self._calculate_entropy(data) > 7.0
        }

    def _calculate_entropy(self, data: bytes) -> float:
        """Calculate Shannon entropy of data"""
        byte_counts = Counter(data)
        entropy = 0
        for count in byte_counts.values():
            probability = count / len(data)
            entropy -= probability * math.log2(probability) if probability > 0 else 0
        return entropy


class NetworkAnomalyDetector:
    """Detects anomalies in network traffic"""

    def detect_anomalies(self, connection_data: Dict) -> List[str]:
        anomalies = []
        if connection_data.get('bytes_sent', 0) > 1000000:
            anomalies.append('large_transfer')
        if connection_data.get('status') == 'ESTABLISHED':
            anomalies.append('persistent_connection')
        return anomalies


